/**
 * A single chunk extracted from / to be written into a savestate.
 */
typedef struct StateChunk StateChunk;

/**
 * FFI descriptor for a single SFORMAT entry (mirrors C++ `struct SFORMAT`).
 *
 * Layout must match C++ exactly:
 * ```c
 * struct SFORMAT { void *v; uint32 s; const char *desc; };
 * ```
 * On x64: v(8) + s(4) + pad(4) + desc(8) = 24 bytes.
 *
 * `v` points to the data in C++ memory. `s` encodes size plus flags
 * (RLSB = byte-swap, INDIRECT = pointer indirection). `desc` is a
 * 4-byte ASCII tag (pointer to static string in C++).
 */
typedef struct FceuxSformatEntry {
  const uint8_t *v;
  uint32_t s;
  uint32_t _pad;
  const uint8_t *desc;
} FceuxSformatEntry;

/**
 * Input chunk descriptor for saving.
 */
typedef struct FceuStateChunkInput {
  uint8_t chunk_type;
  const uint8_t *data;
  uintptr_t len;
} FceuStateChunkInput;

/**
 * Buffer descriptor returned by save / used by free.
 */
typedef struct FceuStateBuffer {
  uint8_t *ptr;
  uintptr_t len;
  uintptr_t cap;
} FceuStateBuffer;

/**
 * Output chunk descriptor for loading.
 *
 * hotfix1 P1-4 (C-06): added an explicit `cap` so the matching
 * `Vec::from_raw_parts` in `state_file_chunks_free` reconstructs the
 * exact same capacity `Vec::with_capacity` produced originally. Without
 * `cap`, the previous code passed `cap = chunk.len` which silently
 * truncated deallocations and could cause a mismatched-deallocation UB
 * at shutdown if a single chunk had been reallocated away from its
 * initial capacity.
 */
typedef struct FceuStateChunkOutput {
  uint8_t chunk_type;
  uint8_t *data;
  uintptr_t len;
  uintptr_t cap;
} FceuStateChunkOutput;

/**
 * Serialize SFORMAT entries into a byte stream (the SFORMAT chunk payload).
 *
 * # Safety
 * `entries` must point to a valid array of `count` SFORMAT entries.
 * Each entry's `v` pointer must be valid for reads of `entry.s & !FLAGS` bytes.
 * The array must be terminated by an entry with `v == null`.
 */
bool fceux11_rust_sformat_serialize(const struct FceuxSformatEntry *entries,
                                    uintptr_t count,
                                    uint8_t **out_buf,
                                    uintptr_t *out_len);

/**
 * Free a buffer returned by `fceux11_rust_sformat_serialize`.
 */
void fceux11_rust_sformat_buf_free(uint8_t *buf, uintptr_t len);

/**
 * Compute CRC32 checksum of a raw SFORMAT byte stream.
 *
 * The SFORMAT binary format is:
 * ```text
 * For each entry: [desc: 4 bytes][size: u32 LE][data: size bytes]
 * ```
 *
 * This function validates the stream structure and returns a CRC32
 * checksum for integrity verification. Returns 0 for empty streams.
 *
 * # Safety
 * `data` must point to `len` valid bytes.
 */
uint32_t fceux11_rust_sformat_crc32(const uint8_t *data, uintptr_t len);

/**
 * Validate SFORMAT byte stream structure.
 *
 * Walks the stream checking that each entry's declared size fits
 * within the remaining bytes. Returns the number of valid entries
 * found, or -1 if the stream is truncated/corrupt.
 *
 * # Safety
 * `data` must point to `len` valid bytes.
 */
int32_t fceux11_rust_sformat_validate(const uint8_t *data, uintptr_t len);

/**
 * Serialize an SFORMAT table into a `StateChunk` with the given chunk type.
 *
 * This is the Rust equivalent of the C++ `addSformatChunk` lambda in
 * `FCEUSS_SaveMS`. It reads from C++ memory via the SFORMAT entries and
 * produces a `StateChunk` ready for V2 file assembly.
 *
 * # Safety
 * Same as `fceux11_rust_sformat_serialize`.
 */
bool fceux11_rust_sformat_to_chunk(const struct FceuxSformatEntry *entries,
                                   uintptr_t count,
                                   uint8_t chunk_type,
                                   struct StateChunk *out_chunk);

/**
 * Serialize chunks into a V1 (FCSX) savestate file buffer.
 *
 * On success, returns `true` and writes a `FceuStateBuffer` to `out_buf`.
 * The caller must free `out_buf.ptr` via `fceux11_rust_state_file_buf_free`.
 * # Safety
 * Callers must ensure all raw pointer arguments passed to `fceux11_rust_state_file_save` are valid.
 */
bool fceux11_rust_state_file_save(const struct FceuStateChunkInput *chunks,
                                  uintptr_t chunk_count,
                                  uint32_t version,
                                  int32_t compression_level,
                                  struct FceuStateBuffer *out_buf);

/**
 * Serialize chunks into a V2 (FCEU11ST) savestate file buffer.
 *
 * On success, returns `true` and writes a `FceuStateBuffer` to `out_buf`.
 * The caller must free `out_buf.ptr` via `fceux11_rust_state_file_buf_free`.
 * # Safety
 * Callers must ensure all raw pointer arguments passed to this function are valid.
 */
bool fceux11_rust_state_file_save_v2(const struct FceuStateChunkInput *chunks,
                                     uintptr_t chunk_count,
                                     int32_t compression_level,
                                     struct FceuStateBuffer *out_buf);

/**
 * Deserialize a savestate file buffer into chunks.
 *
 * Auto-detects V1 (FCSX) and V2 (FCEU11ST) formats.
 *
 * On success, returns `true` and writes:
 * * `out_chunks` — pointer to an array of `FceuStateChunkOutput`
 * * `out_chunk_count` — number of chunks
 * * `out_version` — savestate version from header (format version for V2)
 * * `out_totalsize` — uncompressed payload size
 *
 * The caller must free `out_chunks` via `fceux11_rust_state_file_chunks_free`.
 * # Safety
 * Callers must ensure all raw pointer arguments passed to `fceux11_rust_state_file_load` are valid.
 */
bool fceux11_rust_state_file_load(const uint8_t *file_data,
                                  uintptr_t file_len,
                                  struct FceuStateChunkOutput **out_chunks,
                                  uintptr_t *out_chunk_count,
                                  uint32_t *out_version,
                                  uint32_t *out_totalsize);

/**
 * Free a buffer previously returned by `fceux11_rust_state_file_save`.
 */
void fceux11_rust_state_file_buf_free(struct FceuStateBuffer buf);

/**
 * Free chunks previously returned by `fceux11_rust_state_file_load`.
 * # Safety
 * Callers must ensure all raw pointer arguments passed to `fceux11_rust_state_file_chunks_free` are valid.
 */
void fceux11_rust_state_file_chunks_free(struct FceuStateChunkOutput *chunks,
                                         uintptr_t chunk_count);
